//! Ported from `tests/Sobreiro.Tests/AlertStateTests.cs`, with tests of the bytes written and
//! of the files that load as empty.
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde_json::Value;
use sobreiro_core::alerts::alert_state::{AlertMark, AlertState};
use sobreiro_core::limits::LimitKind;

use crate::{TestFolder, unix};

fn state_of(marks: &[(LimitKind, AlertMark)]) -> AlertState {
    AlertState {
        marks: marks.iter().copied().collect::<BTreeMap<_, _>>(),
    }
}

fn mark(resets_at: Option<i64>, threshold: i32) -> AlertMark {
    AlertMark {
        resets_at: resets_at.map(unix),
        threshold,
    }
}

/// The folder's `alerts.json`, with `text` in it.
fn file_with(folder: &TestFolder, text: &str) -> PathBuf {
    folder.create();
    let path = folder.file("alerts.json");
    std::fs::write(&path, text).unwrap();
    path
}

fn json_of(path: &Path) -> Value {
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn round_trips() {
    let folder = TestFolder::new("alert_state_round_trips");
    let path = folder.file("alerts.json");
    state_of(&[
        (LimitKind::Session, mark(Some(1_738_425_600), 80)),
        (LimitKind::Weekly, mark(None, 95)),
    ])
    .save(&path)
    .unwrap();

    let loaded = AlertState::load(&path);
    assert_eq!(loaded.marks.len(), 2);
    assert_eq!(
        loaded.marks[&LimitKind::Session],
        mark(Some(1_738_425_600), 80)
    );
    assert_eq!(loaded.marks[&LimitKind::Weekly], mark(None, 95));
}

#[test]
fn uses_the_documented_keys_and_values() {
    let folder = TestFolder::new("alert_state_keys");
    let path = folder.file("alerts.json");
    state_of(&[(LimitKind::Spend, mark(Some(100), 80))])
        .save(&path)
        .unwrap();
    let json = json_of(&path);
    assert_eq!(json["spend"]["resets_at"].as_i64(), Some(100));
    assert_eq!(json["spend"]["threshold"].as_i64(), Some(80));
}

#[test]
fn missing_or_corrupt_file_gives_empty() {
    let folder = TestFolder::new("alert_state_corrupt");
    assert!(
        AlertState::load(&folder.file("alerts.json"))
            .marks
            .is_empty()
    );
    let path = file_with(&folder, "{oops");
    assert!(AlertState::load(&path).marks.is_empty());
    std::fs::write(&path, "[1]").unwrap();
    assert!(AlertState::load(&path).marks.is_empty());
}

#[test]
fn credits_mark_round_trips_as_copilot_credits() {
    let folder = TestFolder::new("alert_state_credits");
    let path = folder.file("alerts.json");
    let credits = mark(Some(1_764_547_200), 95);
    state_of(&[(LimitKind::Credits, credits)])
        .save(&path)
        .unwrap();

    let json = json_of(&path);
    assert!(json.get("copilot_credits").is_some());
    assert!(json.get("spend").is_none());
    assert_eq!(AlertState::load(&path).marks[&LimitKind::Credits], credits);
}

#[test]
fn old_file_without_credits_still_loads() {
    let folder = TestFolder::new("alert_state_old_file");
    let path = file_with(
        &folder,
        "{\"session\":{\"resets_at\":1738425600,\"threshold\":80}}",
    );
    let loaded = AlertState::load(&path);
    assert_eq!(loaded.marks.len(), 1);
    assert!(loaded.marks.contains_key(&LimitKind::Session));
}

#[test]
fn saves_the_bytes_the_csharp_wrote() {
    let folder = TestFolder::new("alert_state_bytes");
    let path = folder.file("alerts.json");
    state_of(&[
        (LimitKind::Credits, mark(Some(1_764_547_200), 95)),
        (LimitKind::Session, mark(Some(1_738_425_600), 80)),
        (LimitKind::Weekly, mark(None, 95)),
    ])
    .save(&path)
    .unwrap();
    let expected = [
        "{",
        "  \"session\": {",
        "    \"resets_at\": 1738425600,",
        "    \"threshold\": 80",
        "  },",
        "  \"weekly\": {",
        "    \"resets_at\": null,",
        "    \"threshold\": 95",
        "  },",
        "  \"copilot_credits\": {",
        "    \"resets_at\": 1764547200,",
        "    \"threshold\": 95",
        "  }",
        "}",
    ]
    .join("\r\n");
    assert_eq!(std::fs::read(&path).unwrap(), expected.as_bytes());
}

#[test]
fn an_empty_state_saves_an_empty_object() {
    let folder = TestFolder::new("alert_state_empty_bytes");
    let path = folder.file("alerts.json");
    AlertState::empty().save(&path).unwrap();
    assert_eq!(std::fs::read(&path).unwrap(), b"{}");
}

#[test]
fn an_entry_that_is_not_read_is_skipped() {
    let folder = TestFolder::new("alert_state_skipped");
    let text = r#"{"session":{"threshold":80.0},"weekly":{"threshold":1e2},
        "spend":{"threshold":2147483648},"copilot_credits":[1]}"#;
    assert!(AlertState::load(&file_with(&folder, text)).marks.is_empty());
    let text = r#"{"session":{"threshold":"80"},"weekly":5,"spend":{"resets_at":1}}"#;
    assert!(AlertState::load(&file_with(&folder, text)).marks.is_empty());
}

#[test]
fn a_reset_time_that_is_no_whole_number_is_left_out_of_the_mark() {
    let folder = TestFolder::new("alert_state_odd_reset");
    let text = r#"{"session":{"resets_at":1.5,"threshold":80},
        "weekly":{"resets_at":"x","threshold":90}}"#;
    let loaded = AlertState::load(&file_with(&folder, text));
    assert_eq!(loaded.marks[&LimitKind::Session], mark(None, 80));
    assert_eq!(loaded.marks[&LimitKind::Weekly], mark(None, 90));
}

#[test]
fn a_reset_time_outside_the_years_1_to_9999_empties_the_whole_file() {
    let folder = TestFolder::new("alert_state_far_reset");
    for seconds in [253_402_300_800_i64, -62_135_596_801, i64::MAX] {
        let text = format!(
            r#"{{"session":{{"resets_at":1738425600,"threshold":80}},"weekly":{{"resets_at":{seconds},"threshold":90}}}}"#
        );
        let loaded = AlertState::load(&file_with(&folder, &text));
        assert!(loaded.marks.is_empty(), "{seconds}");
    }
    let text = r#"{"session":{"resets_at":253402300799,"threshold":80}}"#;
    let loaded = AlertState::load(&file_with(&folder, text));
    assert_eq!(
        loaded.marks[&LimitKind::Session].resets_at,
        Some(unix(253_402_300_799))
    );
}

#[test]
fn a_far_reset_time_in_an_entry_that_is_skipped_does_not_empty_the_file() {
    let folder = TestFolder::new("alert_state_far_reset_skipped");
    let text = r#"{"session":{"resets_at":1738425600,"threshold":80},
        "weekly":{"resets_at":999999999999999,"threshold":"x"}}"#;
    let loaded = AlertState::load(&file_with(&folder, text));
    assert_eq!(loaded.marks.len(), 1);
}

#[test]
fn a_byte_order_mark_is_dropped() {
    let folder = TestFolder::new("alert_state_bom");
    folder.create();
    let path = folder.file("alerts.json");
    let mut bytes = vec![0xEF, 0xBB, 0xBF];
    bytes.extend_from_slice(br#"{"weekly":{"resets_at":null,"threshold":95}}"#);
    std::fs::write(&path, bytes).unwrap();
    assert_eq!(
        AlertState::load(&path).marks[&LimitKind::Weekly],
        mark(None, 95)
    );
}

#[test]
fn a_key_with_a_lone_surrogate_escape_does_not_stop_the_load() {
    // 1.x's `TryGetProperty` threw `InvalidOperationException` on such a key, which its `Load`
    // did not catch. Core cannot fail here: the key gives no text, so it matches no limit.
    let folder = TestFolder::new("alert_state_lone_surrogate_key");
    let text = r#"{"\ud800":1,"session":{"resets_at":1738425600,"threshold":80}}"#;
    let loaded = AlertState::load(&file_with(&folder, text));
    assert_eq!(
        loaded.marks[&LimitKind::Session],
        mark(Some(1_738_425_600), 80)
    );
    // Inside an entry such a key stopped nothing in 1.x either: both read the mark.
    let text = r#"{"session":{"\udc00":1,"resets_at":1738425600,"threshold":80}}"#;
    let loaded = AlertState::load(&file_with(&folder, text));
    assert_eq!(loaded.marks.len(), 1);
}

#[test]
fn a_file_in_another_encoding_gives_the_empty_state() {
    // 1.x read a file with a UTF-16 or UTF-32 byte order mark as text. Core reads UTF-8, as the
    // file is written, and gives the empty state for another encoding.
    let folder = TestFolder::new("alert_state_other_encodings");
    folder.create();
    let path = folder.file("alerts.json");
    let text = r#"{"session":{"resets_at":1738425600,"threshold":80}}"#;
    let utf16: Vec<u8> = text.encode_utf16().flat_map(u16::to_le_bytes).collect();
    let utf16_big: Vec<u8> = text.encode_utf16().flat_map(u16::to_be_bytes).collect();
    let utf32: Vec<u8> = text
        .chars()
        .flat_map(|c| (c as u32).to_le_bytes())
        .collect();
    let utf32_big: Vec<u8> = text
        .chars()
        .flat_map(|c| (c as u32).to_be_bytes())
        .collect();
    let files = [
        [&[0xFF, 0xFE][..], &utf16].concat(),
        [&[0xFE, 0xFF][..], &utf16_big].concat(),
        [&[0xFF, 0xFE, 0, 0][..], &utf32].concat(),
        [&[0, 0, 0xFE, 0xFF][..], &utf32_big].concat(),
        utf16,
    ];
    for bytes in files {
        std::fs::write(&path, bytes).unwrap();
        assert!(AlertState::load(&path).marks.is_empty());
    }
}

#[test]
fn the_load_rows_hold_marks_and_files_that_give_none() {
    assert!(LOAD_ROWS.iter().any(|row| row.1.is_empty()));
    assert!(LOAD_ROWS.iter().any(|row| row.1.len() == 4));
    assert!(
        LOAD_ROWS
            .iter()
            .any(|row| row.1.iter().any(|m| m.1.is_none()))
    );
}

// ---- oracle ----
/// A mark as a row of the oracle holds it: the kind, when it resets in seconds since 1970, and
/// the threshold.
type OracleMark = (&'static str, Option<i64>, i32);

fn state_of_rows(rows: &[OracleMark]) -> AlertState {
    AlertState {
        marks: rows
            .iter()
            .map(|&(kind, resets, threshold)| {
                let kind = match kind {
                    "Session" => LimitKind::Session,
                    "Weekly" => LimitKind::Weekly,
                    "Spend" => LimitKind::Spend,
                    "Credits" => LimitKind::Credits,
                    _ => panic!("no kind named {kind}"),
                };
                (kind, mark(resets, threshold))
            })
            .collect(),
    }
}

fn rows_of_state(state: &AlertState) -> Vec<(String, Option<i64>, i32)> {
    state
        .marks
        .iter()
        .map(|(kind, mark)| {
            (
                format!("{kind:?}"),
                mark.resets_at.map(|at| at.timestamp()),
                mark.threshold,
            )
        })
        .collect()
}

fn rows_of_marks(rows: &[OracleMark]) -> Vec<(String, Option<i64>, i32)> {
    rows.iter()
        .map(|&(kind, resets, threshold)| (kind.to_string(), resets, threshold))
        .collect()
}

#[test]
fn load_answers_as_the_csharp_did() {
    let folder = TestFolder::new("alert_state_oracle_load");
    folder.create();
    let path = folder.file("alerts.json");
    let mut differ = Vec::new();
    for (bytes, expected) in LOAD_ROWS {
        std::fs::write(&path, bytes).unwrap();
        let actual = rows_of_state(&AlertState::load(&path));
        if actual != rows_of_marks(expected) {
            let head = String::from_utf8_lossy(&bytes[..bytes.len().min(120)]).into_owned();
            differ.push(format!("{head}: Core {actual:?}, C# {expected:?}"));
        }
    }
    assert!(
        differ.is_empty(),
        "{}",
        differ.join(
            "
"
        )
    );
}

#[test]
fn save_answers_as_the_csharp_did() {
    let folder = TestFolder::new("alert_state_oracle_save");
    folder.create();
    let path = folder.file("alerts.json");
    for (marks, expected) in SAVE_ROWS {
        state_of_rows(marks).save(&path).unwrap();
        assert_eq!(
            std::fs::read(&path).unwrap(),
            *expected,
            "{marks:?}: {}",
            String::from_utf8_lossy(expected)
        );
    }
}

